      interpretation = "\u0423 \u0432\u0430\u0441 \u0441\u0431\u0430\u043B\u0430\u043D\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E\u0435 \u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u0435 \u043A \u0441\u0435\u0431\u0435. \u0412\u044B \u043F\u0440\u0438\u0437\u043D\u0430\u0451\u0442\u0435 \u0438 \u0441\u0438\u043B\u044C\u043D\u044B\u0435, \u0438 \u0441\u043B\u0430\u0431\u044B\u0435 \u0441\u0442\u043E\u0440\u043E\u043D\u044B.";
      recommendation = "\u0421\u043E\u0445\u0440\u0430\u043D\u044F\u0439\u0442\u0435 \u043F\u0440\u0430\u043A\u0442\u0438\u043A\u0438, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043F\u043E\u043C\u043E\u0433\u0430\u044E\u0442: \u0440\u0435\u0444\u043B\u0435\u043A\u0441\u0438\u044E, \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044E\u0449\u0438\u0435 \u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u044F \u0438 \u0437\u0430\u0431\u043E\u0442\u0443 \u043E \u0441\u0435\u0431\u0435.";
