      interpretation = "\u0412\u044B \u0441\u043A\u043B\u043E\u043D\u043D\u044B \u0432\u043E\u0441\u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0442\u044C \u0441\u0435\u0431\u044F \u043F\u043E\u0437\u0438\u0442\u0438\u0432\u043D\u043E. \u042D\u0442\u043E \u0440\u0435\u0441\u0443\u0440\u0441 \u2014 \u043D\u043E \u0432\u0430\u0436\u043D\u043E, \u0447\u0442\u043E\u0431\u044B \u043E\u043D \u043D\u0435 \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u043B\u0441\u044F \u0432 \u0436\u0451\u0441\u0442\u043A\u043E\u0435 \u043E\u0442\u0440\u0438\u0446\u0430\u043D\u0438\u0435 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438.";
      recommendation = "\u0412\u044B\u0441\u043E\u043A\u0430\u044F \u0441\u0430\u043C\u043E\u043E\u0446\u0435\u043D\u043A\u0430 \u0445\u043E\u0440\u043E\u0448\u043E \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043F\u0441\u0438\u0445\u0438\u043A\u0443. \u0415\u0441\u043B\u0438 \u0435\u0441\u0442\u044C \u0437\u0430\u043F\u0440\u043E\u0441 \u2014 \u043F\u043E\u0440\u0430\u0431\u043E\u0442\u0430\u0439\u0442\u0435 \u043D\u0430\u0434 \u044D\u043C\u043F\u0430\u0442\u0438\u0435\u0439 \u0438 \u0443\u0441\u0442\u043E\u0439\u0447\u0438\u0432\u043E\u0441\u0442\u044C\u044E \u043A \u043A\u0440\u0438\u0442\u0438\u043A\u0435.";
